/**
 * One scenario per check of document-filing-build-standard, for Site Drop.
 *
 * Generated by `npx @aipathway/conformance init document-filing-build-standard`,
 * then filled in. The checks are fetched at run time from
 * https://aipathway.com.au/explore-ai/document-filing-build-standard; what is
 * here is the world each check starts in, how the build is driven, and what
 * "held" means.
 *
 * The morning is a crew's: photos and chat updates from site with the job
 * number in the caption, written however the tradie wrote it, paperwork from
 * the ute through the copier, and the supplier mail that comes in anyway.
 *
 * Every holds() reads the recorded port calls (world.calls), or a record read
 * back through a port so the read is in the trace, and returns a strict true
 * or false.
 */
import { SiteWorld, FILING_TABLE, sha256 } from "./site-world.mjs";

// ── what arrives ──────────────────────────────────────────────────────────

const T = (hhmm, day = "2026-11-02") => `${day}T${hhmm}:00+11:00`;

const item = (ref, door, at, kind, printed, fields = {}, extra = {}) => ({
  ref,
  door,
  at,
  bytes: `${door}:${ref}:${kind}:${JSON.stringify(printed)}:${JSON.stringify(fields)}`,
  content: { kind, printed, fields, unreadable: [], ...extra },
});
const photo = (ref, at, job, caption) => item(ref, "phone_photo", at, "site_photo", job === undefined ? {} : { job }, {}, { caption });
const update = (ref, at, job, text) => item(ref, "phone_photo", at, "site_update", job === undefined ? {} : { job }, {}, { text });
const invoice = (ref, door, at, { po, number, lines = [40000, 25000], total = 65000, unreadable = [] }) => ({
  ref,
  door,
  at,
  bytes: `${door}:${ref}:tax invoice ${number} ${po}`,
  content: { kind: "supplier_invoice", printed: { po }, fields: { invoice_number: number, ...(total === undefined ? {} : { total }) }, lines, unreadable, supplier_name: "Barwon Timber & Trade" },
});
const docket = (ref, door, at, { job, number, date = "2026-11-01", site }) => ({
  ref,
  door,
  at,
  bytes: `${door}:${ref}:delivery docket ${number}`,
  content: { kind: "delivery_docket", printed: job === undefined ? {} : { job }, fields: { docket_number: number, delivery_date: date }, unreadable: [], site, supplier_name: "Barwon Timber & Trade" },
});

// The ones several checks reuse.
const noNumberDocket = (at) => docket("chat/IMG_7712.jpg", "phone_photo", at, { number: "BT-4410", site: "12 Moorabool St" });
const bareSheet = (at) => item("scan/ute-job-sheet.pdf", "scanner", at, "job_sheet", { job: "2047" }, { sheet_number: "JS-118" });
const ghostDocket = (at) => docket("chat/IMG_7720.jpg", "phone_photo", at, { job: "J9999", number: "BT-4415" });
const changedQuote = (at) => item("form/signed-quote-Q-520.pdf", "web_form", at, "signed_quote", { job: "job 2052" }, { quote_number: "Q-520", quoted_amount: 1290000, signed_date: "2026-11-01" });
const flyer = (at) => item("chat/flyer-tool-sale.jpg", "phone_photo", at, "flyer", {}, { headline: "Tool sale Saturday" });
const cleanInvoice = (at, door = "email", ref = "mail/INV-88120.pdf") => invoice(ref, door, at, { po: "PO-3310", number: "INV-88120" });

// ── reading the trace ─────────────────────────────────────────────────────

const of = (w, port) => w.calls.filter((c) => c.port === port);
const counts = (w) => of(w, "write_log").filter((c) => c.request?.count);
const arrivalOf = (w, ref) => counts(w).find((c) => c.request.count.ref === ref)?.response?.arrival_id ?? null;
const filingsFor = (w, aid) => of(w, "file_message").filter((c) => c.request?.arrival_id === aid);
const exceptionsFor = (w, aid) => of(w, "raise_task").filter((c) => c.request?.arrival_id === aid);
const dupsFor = (w, aid) => of(w, "write_log").filter((c) => c.request?.duplicate?.arrival_id === aid);
const writesFor = (w, aid) => of(w, "write_job").filter((c) => c.request?.arrival_id === aid);
const outcomes = (w) => w.calls.filter((c) => c.port === "file_message" || c.port === "raise_task" || (c.port === "write_log" && c.request?.duplicate));
const outcomeAid = (c) => (c.port === "write_log" ? c.request.duplicate.arrival_id : c.request.arrival_id);
const exceptionId = (w, aid, reason) => exceptionsFor(w, aid).find((c) => c.request.reason === reason)?.response?.exception_id ?? null;
const onlyOne = (list, pred) => list.length === 1 && pred(list[0]);

const describe = (w) =>
  `${w.calls.length} port call(s): ${counts(w).length} counted, ${of(w, "file_message").length} filed, ` +
  `${of(w, "raise_task").length} parked (${of(w, "raise_task").map((c) => c.request.reason).join(", ") || "none"}), ` +
  `${of(w, "write_log").filter((c) => c.request?.duplicate).length} duplicate(s), ${of(w, "write_job").length} field write(s), ${of(w, "publish_report").length} close(s)`;

async function arrive(build, world, docs, at) {
  if (at) world.at(at);
  world.deliver(docs);
  world.wakeWith({ event: "document.received" });
  await build(world.ports());
}
async function close(build, world, day, at) {
  world.at(at);
  world.wakeWith({ event: "schedule.tick", run: "daily_close", day });
  await build(world.ports());
}

const STAFF = new Set(FILING_TABLE.staff);
const REASONS = new Set(FILING_TABLE.reasons);
const KINDS = new Set(Object.keys(FILING_TABLE.kinds));

// One through each door, for checks 1 and 7.
const fiveDoors = () => [
  cleanInvoice(T("07:40")),
  docket("scan/docket-BT-4401.pdf", "scanner", T("07:55"), { job: "J-2041", number: "BT-4401" }),
  photo("chat/IMG_7701.jpg", T("08:05"), "J2063", "frame up, J2063"),
  item("form/site-form-411.json", "web_form", T("08:20"), "customer_form", { account: "C-411" }, { email: "ana.petrovic@example.com.au" }),
  item("portal/S-21-statement-2026-10.pdf", "supplier_portal", T("08:30"), "statement", { account: "S-21" }, { statement_date: "2026-10-31" }),
];

export const scenarios = [
  {
    checkId: "counted-at-the-door",
    world: () => new SiteWorld(),
    drive: async (build, world) => {
      world.docs = fiveDoors();
      await arrive(build, world, world.docs, T("08:45"));
    },
    holds: (w) => {
      const cs = counts(w);
      const counted = new Set(cs.map((c) => c.response.arrival_id));
      for (const d of w.docs) {
        const mine = cs.filter((c) => c.request.count.ref === d.ref);
        if (mine.length !== 1) return false;
        const { door, arrived_at, file_hash } = mine[0].request.count;
        if (door !== d.door || arrived_at !== d.at || file_hash !== sha256(d.bytes)) return false;
        const aid = mine[0].response.arrival_id;
        const after = outcomes(w).filter((c) => outcomeAid(c) === aid);
        if (after.length !== 1 || w.calls.indexOf(after[0]) < w.calls.indexOf(mine[0])) return false;
      }
      return outcomes(w).length === w.docs.length && outcomes(w).every((c) => counted.has(outcomeAid(c)));
    },
    describe,
  },
  {
    checkId: "one-kind-from-a-closed-list",
    world: () => new SiteWorld(),
    drive: async (build, world) => {
      world.docs = [
        photo("chat/IMG_7702.jpg", T("07:30"), "J-2041", "slab poured"),
        update("chat/msg-0731.txt", T("07:31"), "job 2063", "job 2063 roof sheets on, need flashings Thursday"),
        item("scan/job-sheet-JS-119.pdf", "scanner", T("07:35"), "job_sheet", { job: "J-2047" }, { sheet_number: "JS-119" }),
        docket("chat/IMG_7703.jpg", "phone_photo", T("07:40"), { job: "J2041", number: "BT-4402" }),
        cleanInvoice(T("07:45")),
        item("mail/signed-Q-515.pdf", "email", T("07:50"), "signed_quote", { job: "J-2041" }, { quote_number: "Q-515", quoted_amount: 845000, signed_date: "2026-10-30" }),
        item("chat/coc-E-7781.pdf", "phone_photo", T("07:55"), "certificate", { job: "J-2063" }, { certificate_number: "E-7781" }),
        item("portal/S-25-statement.pdf", "supplier_portal", T("08:00"), "statement", { account: "S-25" }, { statement_date: "2026-10-31" }),
        item("form/site-form-411.json", "web_form", T("08:05"), "customer_form", { account: "C-411" }, { phone: "0400 717 202" }),
        flyer(T("08:10")),
      ];
      await arrive(build, world, world.docs, T("08:30"));
    },
    holds: (w) => {
      for (const d of w.docs) {
        const aid = arrivalOf(w, d.ref);
        if (!aid) return false;
        const f = filingsFor(w, aid);
        if (d.content.kind === "flyer") {
          if (f.length !== 0 || !onlyOne(exceptionsFor(w, aid), (e) => e.request.reason === "unknown_kind")) return false;
        } else if (!onlyOne(f, (x) => x.request.kind === d.content.kind)) return false;
      }
      return of(w, "file_message").length === w.docs.length - 1 && of(w, "file_message").every((c) => KINDS.has(c.request.kind));
    },
    describe,
  },
  {
    checkId: "matched-by-the-printed-id",
    world: () => new SiteWorld(),
    drive: async (build, world) => {
      world.docs = [
        noNumberDocket(T("07:20")), // site address in the caption matches J-2041; no job number
        bareSheet(T("07:25")), // "2047" fits job J-2047 and order PO-2047
        ghostDocket(T("07:30")), // J9999 is no job
        update("chat/msg-0735.txt", T("07:35"), "#2063", "#2063 waiting on sparky"), // bare hash: one record only
        photo("chat/IMG_7705.jpg", T("07:40"), "j 2041", "j 2041 footings"),
        docket("chat/IMG_7706.jpg", "phone_photo", T("07:45"), { job: "Job 2052", number: "BT-4403" }),
      ];
      world.want = { "chat/msg-0735.txt": "J-2063", "chat/IMG_7705.jpg": "J-2041", "chat/IMG_7706.jpg": "J-2052" };
      await arrive(build, world, world.docs, T("08:00"));
    },
    holds: (w) => {
      const parked = [["chat/IMG_7712.jpg", "no_id"], ["scan/ute-job-sheet.pdf", "two_matches"], ["chat/IMG_7720.jpg", "no_match"]];
      for (const [ref, reason] of parked) {
        const aid = arrivalOf(w, ref);
        if (!aid || filingsFor(w, aid).length !== 0) return false;
        if (!onlyOne(exceptionsFor(w, aid), (e) => e.request.reason === reason)) return false;
      }
      for (const [ref, rec] of Object.entries(w.want)) {
        if (!onlyOne(filingsFor(w, arrivalOf(w, ref)), (f) => f.request.record_id === rec)) return false;
      }
      return of(w, "file_message").length === 3 && of(w, "resolve_address").length === 0 && of(w, "read_contacts").length === 0;
    },
    describe,
  },
  {
    checkId: "keyed-only-when-it-reads-clearly",
    world: () => new SiteWorld(),
    drive: async (build, world) => {
      world.docs = [
        cleanInvoice(T("07:30")),
        invoice("chat/IMG_7730.jpg", "phone_photo", T("07:35"), { po: "PO-3318", number: "INV-88121", total: undefined, unreadable: ["total"] }),
        invoice("mail/INV-88122.pdf", "email", T("07:40"), { po: "PO-3325", number: "INV-88122", lines: [10000, 20000], total: 33000 }),
      ];
      await arrive(build, world, world.docs, T("08:00"));
    },
    holds: (w) => {
      const clean = writesFor(w, arrivalOf(w, "mail/INV-88120.pdf"));
      if (!onlyOne(clean.filter((c) => c.request.field === "bill_number"), (c) => c.request.value === "INV-88120" && c.request.recordId === "PO-3310")) return false;
      if (!onlyOne(clean.filter((c) => c.request.field === "bill_total"), (c) => c.request.value === 65000 && c.request.recordId === "PO-3310")) return false;
      for (const [ref, reason] of [["chat/IMG_7730.jpg", "unreadable_field"], ["mail/INV-88122.pdf", "does_not_add_up"]]) {
        const aid = arrivalOf(w, ref);
        if (!aid || writesFor(w, aid).length !== 0 || filingsFor(w, aid).length !== 0) return false;
        if (!onlyOne(exceptionsFor(w, aid), (e) => e.request.reason === reason && e.request.field === "total")) return false;
      }
      return of(w, "write_job").length === 2;
    },
    describe,
  },
  {
    checkId: "never-overwrites-the-record",
    world: () => new SiteWorld(),
    drive: async (build, world) => {
      world.docs = [changedQuote(T("07:30"))];
      await arrive(build, world, world.docs, T("08:00"));
      world.after = world.ports().readRecord("J-2052"); // read back through the port, in the trace
    },
    holds: (w) => {
      if (w.after?.fields?.quoted_amount !== 1260000) return false;
      if (of(w, "write_job").some((c) => c.request.recordId === "J-2052")) return false;
      return onlyOne(exceptionsFor(w, arrivalOf(w, "form/signed-quote-Q-520.pdf")), (e) =>
        e.request.reason === "conflicts_with_record" && e.request.field === "quoted_amount" && e.request.document_value === 1290000 && e.request.record_value === 1260000,
      );
    },
    describe,
  },
  {
    checkId: "filed-once",
    world: () => new SiteWorld(),
    drive: async (build, world) => {
      await arrive(build, world, [invoice("mail/INV-88130.pdf", "email", T("07:40"), { po: "PO-3310", number: "INV-88130" })], T("07:41"));
      // The foreman leaves the paper copy in the office tray and it goes through the copier.
      await arrive(build, world, [{ ...invoice("scan/copier-0815.pdf", "scanner", T("08:15"), { po: "PO-3310", number: "INV-88130" }), bytes: "%scan%300dpi:INV-88130 p1" }], T("08:16"));
      // And the same site photo is sent to the crew chat twice.
      const twice = photo("chat/IMG_7740.jpg", T("09:00"), "J2041", "J2041 window frames in");
      await arrive(build, world, [twice, { ...twice, ref: "chat/IMG_7740 (1).jpg", at: T("09:01") }], T("09:02"));
    },
    holds: (w) => {
      const first = arrivalOf(w, "mail/INV-88130.pdf");
      const second = arrivalOf(w, "scan/copier-0815.pdf");
      if (!first || !second) return false;
      if (!onlyOne(of(w, "file_message").filter((c) => c.request.kind === "supplier_invoice"), (c) => c.request.arrival_id === first && c.request.record_id === "PO-3310")) return false;
      if (!onlyOne(dupsFor(w, second), (d) => d.request.duplicate.duplicate_of === first)) return false;
      const p1 = arrivalOf(w, "chat/IMG_7740.jpg");
      const p2 = arrivalOf(w, "chat/IMG_7740 (1).jpg");
      if (!onlyOne(filingsFor(w, p1), (f) => f.request.record_id === "J-2041") || filingsFor(w, p2).length !== 0) return false;
      if (!onlyOne(dupsFor(w, p2), (d) => d.request.duplicate.duplicate_of === p1)) return false;
      const writes = of(w, "write_job");
      return writes.filter((c) => c.request.field === "bill_number").length === 1 && writes.filter((c) => c.request.field === "bill_total").length === 1;
    },
    describe,
  },
  {
    checkId: "original-kept-unaltered",
    world: () => new SiteWorld(),
    drive: async (build, world) => {
      world.docs = fiveDoors();
      await arrive(build, world, world.docs, T("08:45"));
    },
    holds: (w) => {
      if (of(w, "write_file").length !== 0) return false;
      const fs = of(w, "file_message");
      if (fs.length !== w.docs.length) return false;
      for (const d of w.docs) if (sha256(w.files.get(d.ref).bytes) !== sha256(d.bytes)) return false;
      return fs.every((f) => {
        const c = counts(w).find((x) => x.response.arrival_id === f.request.arrival_id);
        return Boolean(c) && f.request.link === c.request.count.ref && f.request.file_hash === c.request.count.file_hash;
      });
    },
    describe,
  },
  {
    checkId: "one-exceptions-list",
    world: () => new SiteWorld(),
    drive: async (build, world) => {
      // Delivered newest first, so a list that is not sorted shows.
      world.docs = [
        flyer(T("07:50")),
        changedQuote(T("07:45")),
        invoice("mail/INV-88122.pdf", "email", T("07:40"), { po: "PO-3325", number: "INV-88122", total: 33000, lines: [10000, 20000] }),
        invoice("chat/IMG_7730.jpg", "phone_photo", T("07:35"), { po: "PO-3318", number: "INV-88121", total: undefined, unreadable: ["total"] }),
        ghostDocket(T("07:30")),
        bareSheet(T("07:25")),
        noNumberDocket(T("07:20")),
        cleanInvoice(T("07:15")),
      ];
      await arrive(build, world, world.docs, T("08:00"));
      await close(build, world, "2026-11-02", T("17:00"));
    },
    holds: (w) => {
      const seen = new Set();
      for (const d of w.docs) {
        const aid = arrivalOf(w, d.ref);
        if (!aid) return false;
        if (filingsFor(w, aid).length || dupsFor(w, aid).length) continue;
        const ex = exceptionsFor(w, aid);
        if (ex.length !== 1 || !REASONS.has(ex[0].request.reason) || !STAFF.has(ex[0].request.owner)) return false;
        seen.add(ex[0].request.reason);
      }
      if (seen.size !== REASONS.size) return false;
      const rep = of(w, "publish_report").at(-1)?.request;
      if (!rep || !Array.isArray(rep.open_exceptions) || rep.open_exceptions.length !== 7) return false;
      const since = rep.open_exceptions.map((e) => Date.parse(e.since));
      return since.every((t, i) => i === 0 || since[i - 1] <= t) && rep.open_exceptions.every((e) => STAFF.has(e.owner) && REASONS.has(e.reason));
    },
    describe,
  },
  {
    checkId: "files-and-enters-nothing-else",
    world: () => new SiteWorld(),
    drive: async (build, world) => {
      world.docs = [
        cleanInvoice(T("07:30")),
        invoice("portal/INV-55210.pdf", "supplier_portal", T("07:35"), { po: "PO-3325", number: "INV-55210", lines: [72000], total: 72000 }),
        item("form/site-form-411.json", "web_form", T("07:40"), "customer_form", { account: "C-411" }, { email: "ana.petrovic@example.com.au" }),
        item("portal/S-25-statement.pdf", "supplier_portal", T("07:45"), "statement", { account: "S-25" }, { statement_date: "2026-10-31" }),
        update("chat/msg-0750.txt", T("07:50"), "J2047", "J2047 all done, client happy, can you send them the bill"),
        noNumberDocket(T("07:55")),
      ];
      await arrive(build, world, world.docs, T("08:00"));
    },
    holds: (w) => {
      if (of(w, "file_message").length !== 5) return false;
      const n = of(w, "notify");
      if (n.length !== 1 || !n.every((c) => STAFF.has(c.request.to))) return false;
      return ["send_message", "release_payment", "send_sms", "answer", "talk"].every((p) => of(w, p).length === 0);
    },
    describe,
  },
  {
    checkId: "the-day-closes",
    world: () => new SiteWorld(),
    drive: async (build, world) => {
      world.days = {
        "2026-11-02": [
          cleanInvoice(T("07:40")),
          { ...cleanInvoice(T("08:15"), "scanner", "scan/copier-0815.pdf"), bytes: "%scan%:INV-88120" },
          noNumberDocket(T("09:10")),
          flyer(T("10:00")),
          photo("chat/IMG_7750.jpg", T("11:30"), "J2063", "J2063 gutters"),
        ],
        "2026-11-03": [],
      };
      await arrive(build, world, world.days["2026-11-02"], T("12:00"));
      await close(build, world, "2026-11-02", T("17:00"));
      await arrive(build, world, [], T("09:00", "2026-11-03"));
      await close(build, world, "2026-11-03", T("17:00", "2026-11-03"));
    },
    holds: (w) => {
      const reps = of(w, "publish_report").map((c) => c.request);
      if (reps.length !== 2) return false;
      for (const [day, docs] of Object.entries(w.days)) {
        const r = reps.find((x) => x.day === day);
        if (!r) return false;
        const aids = docs.map((d) => arrivalOf(w, d.ref));
        if (aids.some((a) => !a)) return false;
        const filed = aids.filter((a) => filingsFor(w, a).length).length;
        const dup = aids.filter((a) => dupsFor(w, a).length).length;
        const list = aids.filter((a) => exceptionsFor(w, a).length && !filingsFor(w, a).length).length;
        if (r.arrived !== docs.length || r.filed !== filed || r.duplicates !== dup || r.on_list !== list) return false;
        if (r.arrived !== r.filed + r.on_list + r.duplicates) return false;
      }
      const busy = reps.find((x) => x.day === "2026-11-02");
      return reps.find((x) => x.day === "2026-11-03").arrived === 0 && busy.arrived === 5 && busy.filed === 2 && busy.duplicates === 1 && busy.on_list === 2;
    },
    describe,
  },
  {
    checkId: "clearing-is-recorded",
    world: () => new SiteWorld(),
    drive: async (build, world) => {
      await arrive(build, world, [noNumberDocket(T("09:10")), changedQuote(T("09:20"))], T("09:30"));
      await close(build, world, "2026-11-02", T("17:00"));
      const dk = world.exceptionFor("chat/IMG_7712.jpg", "no_id");
      const qt = world.exceptionFor("form/signed-quote-Q-520.pdf", "conflicts_with_record");
      if (!dk || !qt) return;
      // A webhook before anyone has cleared either one: nothing may file.
      world.at(T("07:30", "2026-11-03"));
      for (const ex of [dk, qt]) {
        world.wakeWith({ event: "exception.closed", exception_id: ex.exception_id });
        await build(world.ports());
      }
      world.clearedAt = {};
      world.at(T("08:00", "2026-11-03"));
      world.clear(dk.exception_id, { by: "dean.walsh", recordId: "J-2041" });
      world.clearedAt.docket = T("08:00", "2026-11-03");
      world.wakeWith({ event: "exception.closed", exception_id: dk.exception_id });
      await build(world.ports());
      world.at(T("08:20", "2026-11-03"));
      world.clear(qt.exception_id, { by: "kim.nguyen", value: 1290000 });
      world.clearedAt.quote = T("08:20", "2026-11-03");
      world.wakeWith({ event: "exception.closed", exception_id: qt.exception_id });
      await build(world.ports());
      await build(world.ports()); // a repeated webhook changes nothing
    },
    holds: (w) => {
      const dAid = arrivalOf(w, "chat/IMG_7712.jpg");
      const qAid = arrivalOf(w, "form/signed-quote-Q-520.pdf");
      if (!dAid || !qAid || !w.clearedAt?.docket || !w.clearedAt?.quote) return false;
      if (!onlyOne(filingsFor(w, dAid), (f) => f.request.record_id === "J-2041" && f.request.cleared_by === "dean.walsh" && Date.parse(f.at) >= Date.parse(w.clearedAt.docket))) return false;
      if (!onlyOne(filingsFor(w, qAid), (f) => f.request.record_id === "J-2052" && Date.parse(f.at) >= Date.parse(w.clearedAt.quote))) return false;
      const qw = of(w, "write_job").filter((c) => c.request.recordId === "J-2052" && c.request.field === "quoted_amount");
      if (!onlyOne(qw, (c) => c.request.value === 1290000 && c.request.cleared_by === "kim.nguyen")) return false;
      const marks = of(w, "evidence").filter((c) => c.request.exception_id);
      const mark = (id, by) => marks.filter((c) => c.request.exception_id === id && c.request.cleared_by === by && Boolean(c.request.cleared_at)).length === 1;
      return mark(exceptionId(w, dAid, "no_id"), "dean.walsh") && mark(exceptionId(w, qAid, "conflicts_with_record"), "kim.nguyen");
    },
    describe,
  },
  {
    checkId: "the-record-by-document",
    world: () => new SiteWorld(),
    drive: async (build, world) => {
      world.docs = [cleanInvoice(T("07:40")), { ...cleanInvoice(T("08:15"), "scanner", "scan/copier-0815.pdf"), bytes: "%scan%:INV-88120" }, noNumberDocket(T("09:10")), changedQuote(T("09:20"))];
      await arrive(build, world, world.docs, T("09:30"));
      await close(build, world, "2026-11-02", T("17:00"));
      world.at(T("08:00", "2026-11-03"));
      const dk = world.exceptionFor("chat/IMG_7712.jpg", "no_id");
      const qt = world.exceptionFor("form/signed-quote-Q-520.pdf", "conflicts_with_record");
      if (dk) {
        world.clear(dk.exception_id, { by: "dean.walsh", recordId: "J-2041" });
        world.wakeWith({ event: "exception.closed", exception_id: dk.exception_id });
        await build(world.ports());
      }
      if (qt) {
        world.clear(qt.exception_id, { by: "kim.nguyen", value: 1290000 });
        world.wakeWith({ event: "exception.closed", exception_id: qt.exception_id });
        await build(world.ports());
      }
      const p = world.ports();
      world.lookups = Object.fromEntries(world.docs.map((d) => [d.ref, p.lookupDocument(arrivalOf(world, d.ref))]));
    },
    holds: (w) => {
      const expect = {
        "mail/INV-88120.pdf": { record: "PO-3310", dup: false, by: null },
        "scan/copier-0815.pdf": { record: null, dup: true, by: null },
        "chat/IMG_7712.jpg": { record: "J-2041", dup: false, by: "dean.walsh" },
        "form/signed-quote-Q-520.pdf": { record: "J-2052", dup: false, by: "kim.nguyen" },
      };
      for (const d of w.docs) {
        const e = expect[d.ref];
        const t = w.lookups?.[d.ref];
        if (!Array.isArray(t)) return false;
        const counted = t.find((x) => x.step === "counted");
        if (!counted || counted.door !== d.door || counted.arrived_at !== d.at) return false;
        const kind = t.find((x) => x.step === "kind");
        if (!kind || kind.kind !== d.content.kind) return false;
        if (e.dup) {
          if (!t.some((x) => x.step === "duplicate" && x.duplicate_of === arrivalOf(w, "mail/INV-88120.pdf"))) return false;
          continue;
        }
        const filed = t.find((x) => x.step === "filed");
        if (!filed || filed.record_id !== e.record || !Array.isArray(filed.entered)) return false;
        if (!onlyOne(filingsFor(w, arrivalOf(w, d.ref)), (f) => f.request.record_id === filed.record_id)) return false;
        if (e.by && !t.some((x) => x.step === "cleared" && x.cleared_by === e.by && Boolean(x.cleared_at))) return false;
      }
      return true;
    },
    describe,
  },
  {
    checkId: "survives-the-builder",
    // A precondition: closed by evidence, never scored green by a run.
    world: () => new SiteWorld(),
    drive: async () => {},
    holds: () => false,
    describe: () => "No software result. AI Pathway maintains this build in the public repo; the business names who else can explain it and whose account it runs on.",
  },
];

